def transform(grid):
    h, w = len(grid), len(grid[0])
    outside = set()
    stack = []

    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h - 1 or c == 0 or c == w - 1) and grid[r][c] == 0:
                if (r, c) not in outside:
                    outside.add((r, c))
                    stack.append((r, c))

    while stack:
        r, c = stack.pop()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in outside:
                outside.add((nr, nc))
                stack.append((nr, nc))

    result = [row[:] for row in grid]
    seen = set(outside)
    colors = {3: 8, 5: 4, 7: 3}

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            component = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                cr, cc = stack.pop()
                component.append((cr, cc))
                for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            min_r = min(x[0] for x in component)
            max_r = max(x[0] for x in component)
            min_c = min(x[1] for x in component)
            max_c = max(x[1] for x in component)
            size = max(max_r - min_r + 1, max_c - min_c + 1)
            color = colors.get(size)
            if color is not None:
                for cr, cc in component:
                    result[cr][cc] = color

    return result
